  insert into public.lesson_materials(lesson_id,content) values (v_lesson,'{"skill":"Listening","transcript":"Coordinator: Good morning, everyone, and welcome to the exchange programme. I''m Ruth, and I''ll explain how your first week works.\nEvery morning you''ll meet your host student at the main gate at eight forty-five. Please don''t be late, because lessons begin at nine sharp.\nOn Monday and Wednesday you''ll join normal classes with your host. On Tuesday afternoon we have a cooking workshop in the student kitchen – you''ll make a traditional local soup. On Thursday there''s a trip to the science museum, so wear comfortable shoes; we walk there and it takes about twenty minutes.\nFriday is free in the morning, and in the evening there''s a farewell party in the sports hall. Your host families are invited too.\nOne more thing: lunch is provided in the canteen every day except Thursday. On the museum trip, please bring a packed lunch.\nIf you have any problems, my office is on the first floor, next to the library. Any questions? No? Great, enjoy your week!","audioUrl":"","figure":{"url":"","alt":""}}'::jsonb)
