  insert into public.lesson_materials(lesson_id,content) values (v_lesson,'{"skill":"Vocabulary","introduction":"Homes appear in IELTS Listening Section 1 (renting a room, booking accommodation) and in Speaking Part 1 (''Tell me about your home''). Learn these words for places and objects, notice the pairs that are easy to confuse (fridge / freezer, curtains / blinds), then write your own sentence.\n\nMẹo: học theo cặp từ dễ nhầm để nghe đúng trong bài Listening.","figure":{"url":"","alt":""}}'::jsonb)
  on conflict (lesson_id) do update set content=excluded.content, updated_at=now();
