  values (v_lesson,'hallway','/ˈhɔːlweɪ/','hành lang (trong nhà)','A narrow space inside a building with doors to other rooms.','Please leave your shoes in the hallway.','Viết bằng tiếng Anh: Hành lang nhà tôi rất hẹp.','["The hallway in my house is very narrow.","My hallway is very narrow."]'::jsonb,0)
  on conflict (lesson_id,word) do update set phonetic=excluded.phonetic, meaning_vi=excluded.meaning_vi, definition=excluded.definition, example=excluded.example, sentence_prompt_vi=excluded.sentence_prompt_vi, accepted_sentences=excluded.accepted_sentences, sort_order=excluded.sort_order;
  insert into public.vocabulary_entries(lesson_id,word,phonetic,meaning_vi,definition,example,sentence_prompt_vi,accepted_sentences,sort_order)
  values (v_lesson,'attic','/ˈætɪk/','gác mái','A room or space just under the roof of a house.','We keep old books and toys in the attic.','Viết bằng tiếng Anh: Chúng tôi cất đồ cũ trên gác mái.','["We keep old things in the attic.","We store old things in the attic."]'::jsonb,1)
  on conflict (lesson_id,word) do update set phonetic=excluded.phonetic, meaning_vi=excluded.meaning_vi, definition=excluded.definition, example=excluded.example, sentence_prompt_vi=excluded.sentence_prompt_vi, accepted_sentences=excluded.accepted_sentences, sort_order=excluded.sort_order;
  insert into public.vocabulary_entries(lesson_id,word,phonetic,meaning_vi,definition,example,sentence_prompt_vi,accepted_sentences,sort_order)
  values (v_lesson,'basement','/ˈbeɪsmənt/','tầng hầm','A room or floor of a building that is below the ground.','The washing machine is in the basement.','Viết bằng tiếng Anh: Tầng hầm thì lạnh và tối.','["The basement is cold and dark."]'::jsonb,2)
  on conflict (lesson_id,word) do update set phonetic=excluded.phonetic, meaning_vi=excluded.meaning_vi, definition=excluded.definition, example=excluded.example, sentence_prompt_vi=excluded.sentence_prompt_vi, accepted_sentences=excluded.accepted_sentences, sort_order=excluded.sort_order;
  insert into public.vocabulary_entries(lesson_id,word,phonetic,meaning_vi,definition,example,sentence_prompt_vi,accepted_sentences,sort_order)
  values (v_lesson,'garage','/ˈɡærɑːʒ/','nhà để xe','A building or room where you keep a car or motorbike.','My dad parks his motorbike in the garage.','Viết bằng tiếng Anh: Xe đạp của tôi ở trong nhà để xe.','["My bike is in the garage.","My bicycle is in the garage."]'::jsonb,3)
