  values (v_lesson,'shared kitchen','/ʃeəd ˈkɪtʃɪn/','bếp dùng chung','A kitchen that several people who live in the same building use.','In my student hall, ten students use one shared kitchen.','Viết bằng tiếng Anh: Tôi nấu ăn trong bếp dùng chung.','["I cook in a shared kitchen.","I cook in the shared kitchen."]'::jsonb,9)
  on conflict (lesson_id,word) do update set phonetic=excluded.phonetic, meaning_vi=excluded.meaning_vi, definition=excluded.definition, example=excluded.example, sentence_prompt_vi=excluded.sentence_prompt_vi, accepted_sentences=excluded.accepted_sentences, sort_order=excluded.sort_order;

  -- Grammar: Present simple: negatives and questions
  insert into public.lessons(unit_id,slug,title,skill,summary,sort_order,published)
  values (v_unit,'starter-u02-grammar-questions-negatives','Present simple: negatives and questions','Grammar','Make negatives, questions and short answers with do and does.',2,false)
  on conflict (slug) do update set unit_id=excluded.unit_id, title=excluded.title, skill=excluded.skill, summary=excluded.summary, sort_order=excluded.sort_order, updated_at=now() returning id into v_lesson;
  insert into public.lesson_materials(lesson_id,content) values (v_lesson,'{"skill":"Grammar","rule":"Negatives: subject + don''t / doesn''t + base verb.\n• I don''t live near the city centre.\n• She doesn''t have a balcony. (NOT: She doesn''t has)\n\nQuestions: Do / Does + subject + base verb?\n• Do you share a room?   • Does the flat have Wi-Fi?\n• Wh- questions: Where do you live? How much does it cost?\n\nShort answers repeat do/does, not the main verb:\n• Do you rent your flat? – Yes, I do. / No, I don''t.\n• Does he live alone? – Yes, he does. / No, he doesn''t.\n\nGhi nhớ: sau does / doesn''t, động từ chính về nguyên mẫu (không thêm -s).","example":"Does your apartment have a garden? – No, it doesn''t, but it has a big balcony.","figure":{"url":"","alt":""}}'::jsonb)
  on conflict (lesson_id) do update set content=excluded.content, updated_at=now();
