  -- Reading: A guide to student housing
  insert into public.lessons(unit_id,slug,title,skill,summary,sort_order,published)
  values (v_unit,'starter-u02-reading-student-housing-guide','A guide to student housing','Reading','Read a housing guide and answer note-style and True/False/Not Given questions.',3,false)
  on conflict (slug) do update set unit_id=excluded.unit_id, title=excluded.title, skill=excluded.skill, summary=excluded.summary, sort_order=excluded.sort_order, updated_at=now() returning id into v_lesson;
  insert into public.lesson_materials(lesson_id,content) values (v_lesson,'{"skill":"Reading","passage":"Choosing where to live: a guide for new students\n\nMost first-year students choose between three types of accommodation.\n\nCollege halls are large buildings on or next to the campus. Each student has a private bedroom with a desk and a single bed, but bathrooms and kitchens are shared by everyone on the same floor. Rent includes electricity, water and internet, which makes it easy to plan a budget. The halls are lively and it is easy to make friends, although some students find them noisy during exam periods.\n\nA homestay means living with a local family in their house. Breakfast and dinner are usually included in the weekly price. This option is popular with students who want to practise English every day, but houses are often a long way from the college, so students may need to commute for 40 minutes or more.\n\nPrivate flats are rented directly from a landlord and are usually shared by two to four people. They give students the most independence, and they can be cheaper if the rent is divided between several flatmates. However, bills are not normally included, and tenants must sign a contract for at least six months.\n\nThe accommodation office in Building C can help you compare options. It is open from Monday to Friday, 9 a.m. to 4 p.m.","figure":{"url":"","alt":""}}'::jsonb)
  on conflict (lesson_id) do update set content=excluded.content, updated_at=now();
