  on conflict (slug) do update set unit_id=excluded.unit_id, title=excluded.title, skill=excluded.skill, summary=excluded.summary, sort_order=excluded.sort_order, updated_at=now() returning id into v_lesson;
  insert into public.lesson_materials(lesson_id,content) values (v_lesson,'{"skill":"Listening","transcript":"Officer: Good afternoon, accommodation office. How can I help?\nStudent: Hi, I''m starting a course next month and I''m looking for a room.\nOfficer: Sure. Can I have your name, please?\nStudent: It''s Duc Nguyen. That''s D-U-C, and Nguyen is N-G-U-Y-E-N.\nOfficer: Thank you. What kind of accommodation are you looking for?\nStudent: A room in a shared flat, I think. Halls are a bit noisy for me.\nOfficer: OK. We have one in Park Street, number 28. It''s a three-bedroom flat, and you''d share it with two other students.\nStudent: How much is the rent?\nOfficer: It''s 140 pounds a week. Gas and electricity are extra, but the internet is included.\nStudent: Is the flat furnished?\nOfficer: Yes, there''s a bed, a desk and a wardrobe in your room. The kitchen has a fridge and a washing machine, but there isn''t a dishwasher.\nStudent: That''s fine. How far is it from the campus?\nOfficer: About fifteen minutes by bike. There''s a bus too, but it only runs every half an hour.\nStudent: Can I see it before I decide?\nOfficer: Of course. The landlord can show you round on Saturday at ten thirty.\nStudent: Perfect, thank you.","audioUrl":"","figure":{"url":"","alt":""}}'::jsonb)
