  on conflict (slug) do update set unit_id=excluded.unit_id, title=excluded.title, skill=excluded.skill, summary=excluded.summary, sort_order=excluded.sort_order, updated_at=now() returning id into v_lesson;
  insert into public.lesson_materials(lesson_id,content) values (v_lesson,'{"skill":"Writing","prompt":"Your friend Mai wants to know about your new accommodation. Write an email to Mai (60–80 words). In your email:\n• describe your room and the building\n• say who you live with\n• say what you like or don''t like about it.\nStart with ''Hi Mai,'' and finish with a short closing such as ''Write soon,'' and your name.","minWords":60,"modelAnswer":"Hi Mai,\n\nThanks for your email. I''m living in a shared flat near the college now. My room is small, but it has a big window, a desk and a comfortable bed. I share the kitchen and bathroom with two other students from Spain and Korea, and we often cook together. I really like the location because I can walk to class. The only problem is that the street is a bit noisy at night.\n\nWrite soon,\nHoa","checklist":["Start with a greeting and end with a closing","Answer all three bullet points","Use capital letters and full stops correctly","Use the present simple for facts about your home","Write 60–80 words"],"figure":{"url":"","alt":""}}'::jsonb)
  on conflict (lesson_id) do update set content=excluded.content, updated_at=now();

